def regime(a, lr):
    r = 1 - lr * a
    if abs(r) > 1:
        return 'diverges'
    if abs(r) == 1:
        return 'stuck'
    if r < 0:
        return 'zigzag'
    return 'smooth'

import numpy as np

def lr_schedule(t, total, warmup, peak):
    t = np.asarray(t, dtype=float)
    warm = peak * t / warmup
    decay = peak * 0.5 * (1 + np.cos(np.pi * (t - warmup) / (total - warmup)))
    return np.where(t < warmup, warm, decay)
